import{_ as a,c as o,o as s,ah as n,ao as t,ap as i}from"./chunks/framework.Dq2_gudl.js";const v=JSON.parse('{"title":"Más allá del Puente del Arcoíris — El pacto de Dios con todo ser viviente","description":"El Puente del Arcoíris es una imagen hermosa, pero el arcoíris de la Biblia es mayor: un pacto eterno que Dios hizo con todo ser viviente.","frontmatter":{"title":"Más allá del Puente del Arcoíris — El pacto de Dios con todo ser viviente","description":"El Puente del Arcoíris es una imagen hermosa, pero el arcoíris de la Biblia es mayor: un pacto eterno que Dios hizo con todo ser viviente."},"headers":[],"relativePath":"es/pets-in-heaven/rainbow-bridge-covenant.md","filePath":"es/pets-in-heaven/rainbow-bridge-covenant.md"}'),r={name:"es/pets-in-heaven/rainbow-bridge-covenant.md"};function l(p,e,c,d,u,h){return s(),o("div",null,[...e[0]||(e[0]=[n('<div class="pl-quote"><p>«Dicen que cruzó el Puente del Arcoíris. ¿Pero eso es solo algo bonito, o hay esperanza real?»</p><p class="pl-quote-soft">Aquí está la parte sorprendente: la Biblia realmente tiene un arcoíris, y ese pacto fue hecho para los animales.</p></div><section class="pl-section"><h2>1. Ese arcoíris fue un pacto con los animales</h2><p>Después del diluvio, Dios hizo un pacto con Noé, prometiendo no volver a destruir la tierra con agua. Pero las partes de ese pacto no eran solo Noé y sus descendientes:</p><blockquote><p><strong>Génesis 9:9-13</strong></p><p>&quot;And I, behold, I establish my covenant with you, and with your seed after you; And with every living creature that is with you, of the fowl, of the cattle, and of every beast of the earth with you… And the bow shall be in the cloud; and it shall be for a token of a covenant between me and the earth.&quot;</p></blockquote><p>Fíjate en la expresión «<em>todo ser viviente</em>»: las aves, el ganado y todas las bestias de la tierra son nombrados como partes del pacto. Y Dios puso el arcoíris en las nubes como señal <strong>entre Él y la tierra, con todo ser viviente</strong>.</p><p>Este es uno de los hechos más ignorados y más tiernos de toda la Escritura: <strong>Dios una vez hizo, formal y permanentemente, un pacto con los animales.</strong></p><p>Así que el nombre humano «Puente del Arcoíris» no está tan lejos. La Escritura dice que esa luz es una señal, y una señal nunca significa «el final». Significa «todavía hay más».</p></section><section class="pl-section"><h2>2. En el mundo venidero, se acuestan en paz</h2><p>Cuando Isaías describe el mundo que Dios hará, los animales son centrales en la escena:</p><blockquote><p><strong>Isaías 65:25</strong></p><p>&quot;The wolf and the lamb shall feed together, and the lion shall eat straw like the bullock… They shall not hurt nor destroy in all my holy mountain, saith the LORD.&quot;</p></blockquote><p>Y Apocalipsis nos deja oír quién canta en la adoración final:</p><blockquote><p><strong>Apocalipsis 5:13</strong></p><p>&quot;And every creature which is in heaven, and on the earth, and under the earth, and such as are in the sea, and all that are in them, heard I saying, Blessing, and honour, and glory, and power, be unto him that sitteth upon the throne, and unto the Lamb for ever and ever.&quot;</p></blockquote><p>«Toda criatura» está adorando. No solo las personas.</p><p>Y los Salmos lo resumen en una línea corta:</p><blockquote><p><strong>Salmos 150:6</strong></p><p>&quot;Let every thing that hath breath praise the LORD.&quot;</p></blockquote><p>Todo lo que respira — incluido él — está dentro de ese cántico.</p></section><section class="pl-section"><h2>3. Entonces, más allá del puente hay una promesa</h2><p>No podemos añadir promesas en nombre de Dios. Pero podemos permanecer dentro de lo que Él ya dijo: hizo pacto con todo ser viviente; el mundo que Él hará tiene animales viviendo en paz; Su adoración final incluye «toda criatura»; todo lo que respira lo alabará.</p><p>Estos versículos no dicen «tu mascota con seguridad está allí». Pero hacen completamente legítima una oración: «Señor, que esté dentro de Tu promesa». Y este es el Dios que dejó un arcoíris para los animales.</p><p class="pl-quote-soft">Piénsalo: si Dios dejó un arcoíris para los animales, ¿no se acordará del tuyo?</p></section><div class="pl-quote"><p>«Pusiste Tu arco en las nubes como señal con todo ser viviente.<br>Cuando vea esa luz, me acordaré de él.<br>Que esté en paz dentro de Tu promesa, tal como prometiste.<br>Y que Tu pacto me sostenga los días en que lo extraño. Amén.»</p></div><section class="pl-section"><h2>Un pequeño ritual para ti</h2><p>Si aparece un arcoíris después de la lluvia, que sea tu señal. Quédate ahí unos segundos y háblale — sin necesidad de conclusiones, sin necesidad de terminar el pensamiento. En la Escritura esa luz siempre fue «la señal de un pacto», y una señal significa que Dios no ha olvidado.</p><p><a href="/es/pets-in-heaven/">← Volver a Pets in Heaven</a> ｜ Siguiente: <a href="/es/pets-in-heaven/permission-to-grieve">Permiso para llorar</a></p></section><div class="pl-cta"><h2>Guarda los lugares que vieron juntos.</h2><p>Convierte sus fotos en una tarjeta memorial, un póster o un breve vídeo, para que los días que caminaron juntos tengan una forma que permanezca.</p><a class="pl-download" href="https://apps.apple.com/us/app/petloss-memorial-healing/id6757967412">Descargar en el App Store</a></div><div class="pl-bible"><h3>Deja que la Palabra te siga acompañando</h3><p>Todos los versículos de este artículo provienen de la Biblia. Con Rainbow Bible puedes leer las Escrituras en cualquier momento y poner un widget con el versículo del día: una pequeña luz en los días en que lo echas de menos.</p><div class="pl-bible-shots"><figure><img src="'+t+'" alt="Widget de Rainbow Bible mostrando 2 Timoteo 2:13" loading="lazy"><figcaption>Versículo del día en tu pantalla</figcaption></figure><figure><img src="'+i+'" alt="Rainbow Bible — tema Mascotas en el cielo mostrando Mateo 10:29-31" loading="lazy"><figcaption>Lee las Escrituras en Mascotas en el cielo</figcaption></figure></div><a class="pl-bible-download" href="https://apps.apple.com/app/id6756217525">Descargar Rainbow Bible en el App Store</a></div>',8)])])}const b=a(r,[["render",l]]);export{v as __pageData,b as default};
